commands.keystrokes:
echo 'log_path,current_size_mb,days_since_rotation,recommended_schedule,estimated_savings_mb' > /app/rotation_summary.csv
CURRENT_TIME=$(date +%s)
for LOG in /var/log/samples/app.log /var/log/samples/system.log /var/log/samples/access.log /var/log/samples/error.log; do 
  SIZE=$(stat -c %s "$LOG")
  MOD_TIME=$(stat -c %Y "$LOG")
  DAYS=$(( (CURRENT_TIME - MOD_TIME) / 86400 ))
  CUR_SIZE_MB=$(echo "scale=2; $SIZE / 1048576" | bc)
  case "$LOG" in
    */app.log) SCHEDULE="weekly"; EST_SAVINGS=$(echo "scale=2; $CUR_SIZE_MB * 0.3" | bc) ;; 
    */system.log) SCHEDULE="weekly"; EST_SAVINGS=$(echo "scale=2; $CUR_SIZE_MB * 0.3" | bc) ;; 
    */access.log) SCHEDULE="monthly"; EST_SAVINGS=$(echo "scale=2; $CUR_SIZE_MB * 0.2" | bc) ;; 
    */error.log) SCHEDULE="daily"; EST_SAVINGS=$(echo "scale=2; $CUR_SIZE_MB * 0.5" | bc) ;; 
    *) SCHEDULE="weekly"; EST_SAVINGS=0;;
  esac
  printf "%s,%.2f,%d,%s,%.2f\n" "$LOG" "$CUR_SIZE_MB" "$DAYS" "$SCHEDULE" "$EST_SAVINGS" >> /app/rotation_summary.csv
 done
